function perfectpixel_page_logo_meta_box() {
	add_meta_box( 'perfectpixel-page-logo', 'Λογότυπο σελίδας', 'perfectpixel_page_logo_meta_box_html', 'page', 'side', 'low' );
}

function perfectpixel_page_logo_media( $hook ) {
	if ( in_array( $hook, array( 'post.php', 'post-new.php' ), true ) && 'page' === get_current_screen()->post_type ) {
		wp_enqueue_media();
	}
}

function perfectpixel_page_logo_meta_box_html( $post ) {
	$id = (int) get_post_meta( $post->ID, '_perfectpixel_page_logo', true );
	wp_nonce_field( 'perfectpixel_page_logo', 'perfectpixel_page_logo_nonce' );
	?>
	<div class="perfectpixel-page-logo-preview" style="margin-bottom:8px"><?php echo $id ? wp_get_attachment_image( $id, 'medium', false, array( 'style' => 'max-width:100%;height:auto' ) ) : ''; ?></div>
	<input type="hidden" name="perfectpixel_page_logo" class="perfectpixel-page-logo-id" value="<?php echo esc_attr( $id ? $id : '' ); ?>">
	<button type="button" class="button perfectpixel-page-logo-choose"><?php echo 'Επιλογή εικόνας'; ?></button>
	<button type="button" class="button-link perfectpixel-page-logo-remove" style="margin-left:8px<?php echo $id ? '' : ';display:none'; ?>"><?php echo 'Αφαίρεση'; ?></button>
	<script>
	( function () {
		var box = document.getElementById( 'perfectpixel-page-logo' );
		if ( ! box || ! window.wp || ! wp.media ) {
			return;
		}
		var input = box.querySelector( '.perfectpixel-page-logo-id' );
		var preview = box.querySelector( '.perfectpixel-page-logo-preview' );
		var remove = box.querySelector( '.perfectpixel-page-logo-remove' );
		var frame;
		box.querySelector( '.perfectpixel-page-logo-choose' ).addEventListener( 'click', function () {
			frame = frame || wp.media( { library: { type: 'image' }, multiple: false } );
			frame.off( 'select' ).on( 'select', function () {
				var img = frame.state().get( 'selection' ).first().toJSON();
				var src = ( img.sizes && img.sizes.medium ) ? img.sizes.medium.url : img.url;
				input.value = img.id;
				preview.innerHTML = '';
				var el = document.createElement( 'img' );
				el.src = src;
				el.style.maxWidth = '100%';
				el.style.height = 'auto';
				preview.appendChild( el );
				remove.style.display = '';
			} );
			frame.open();
		} );
		remove.addEventListener( 'click', function () {
			input.value = '';
			preview.innerHTML = '';
			remove.style.display = 'none';
		} );
	} )();
	</script>
	<?php
}

function perfectpixel_page_logo_save( $post_id, $post ) {
	if ( ! isset( $_POST['perfectpixel_page_logo_nonce'] ) || ! wp_verify_nonce( sanitize_text_field( wp_unslash( $_POST['perfectpixel_page_logo_nonce'] ) ), 'perfectpixel_page_logo' ) ) {
		return;
	}
	if ( wp_is_post_revision( $post_id ) || ! current_user_can( 'edit_post', $post_id ) ) {
		return;
	}
	$id = isset( $_POST['perfectpixel_page_logo'] ) ? absint( $_POST['perfectpixel_page_logo'] ) : 0;
	if ( $id && wp_attachment_is_image( $id ) ) {
		update_post_meta( $post_id, '_perfectpixel_page_logo', $id );
	} else {
		delete_post_meta( $post_id, '_perfectpixel_page_logo' );
	}
}

function perfectpixel_page_logo_override( $logo ) {
	if ( is_admin() || ! did_action( 'wp' ) || ! is_page() ) {
		return $logo;
	}
	$id = (int) get_post_meta( get_queried_object_id(), '_perfectpixel_page_logo', true );
	return ( $id && wp_attachment_is_image( $id ) ) ? $id : $logo;
}
